// spec: .qa/e2e/specs/devices.md (3.1)
// seed: tests/seed.user.spec.ts
// НИКОГДА не нажимать «הסרה», «שמירה».
import { test, expect } from '@playwright/test';
import path from 'node:path';

test.use({ storageState: path.join(__dirname, '../../../auth/user.json') });

test.describe('«מכשירים» — окно удаления телефона', () => {
  test('Окно «הסרת הטלפון מהחשבון» = Figma 05.4, «ביטול» ничего не удаляет #ec8ab82d #1c852837 @desktop @prod-safe', async ({ page }) => {
    // 1. /account/devices, список, число строк
    await page.goto('/account/devices');
    const rows = page.getByRole('button', { name: /, (מחובר|לא מחובר)$/ }).filter({ visible: true });
    await expect(rows.first()).toBeVisible();
    const count = await rows.count();
    expect(count).toBe(2);

    // 2. Своя строка → окно роли
    await rows.filter({ hasText: 'הטלפון הזה' }).click();
    const dialog = page.getByRole('dialog').filter({ visible: true });
    await expect(dialog.getByText('מה הטלפון הזה עושה?')).toBeVisible();

    // 3. «הסרת הטלפון מהחשבון» → окно подтверждения
    await dialog.getByRole('button', { name: 'הסרת הטלפון מהחשבון' }).click();

    // 4. Содержимое окна (Figma 05.4, 264:5916)
    const title = dialog.getByRole('heading', { name: /^להסיר את .+\?$/ });
    await expect(title).toBeVisible();
    // Для своего телефона перед фразой стоит «זה הטלפון שבידכם.» (принято 08.10)
    await expect(dialog.getByText(/(הטלפון|הוא) ינותק מהחשבון\./)).toBeVisible();
    await expect(dialog.getByText('אפשר לחבר אותו שוב בכל רגע.')).toBeVisible();
    await expect(dialog.getByText(/הטלפון לא יקבל התרעות/).first()).toBeVisible();
    await expect(dialog.getByText(/הוא יוסר מרשימת הטלפונים/).first()).toBeVisible();
    const remove = dialog.getByRole('button', { name: 'הסרה', exact: true });
    await expect(remove).toBeVisible();
    await expect(remove.locator('svg, img').first()).toBeAttached(); // иконка корзины
    await expect(dialog.getByRole('button', { name: 'ביטול', exact: true })).toBeVisible();

    // 5. «ביטול» (НЕ «הסרה») → окно роли; закрыть «סגירה»
    await dialog.getByRole('button', { name: 'ביטול', exact: true }).click();
    await expect(page.getByRole('heading', { name: /^להסיר את / }).filter({ visible: true })).toHaveCount(0);
    await expect(dialog.getByText('מה הטלפון הזה עושה?')).toBeVisible();
    // «סגירה» — затемнённый фон над окном: нажимаем в его верхний угол, не в центр (в центре — переключатели роли). НЕ «שמירה».
    await dialog.getByRole('button', { name: 'סגירה' }).click({ position: { x: 8, y: 8 } });
    await expect(page.getByRole('dialog').filter({ visible: true })).toHaveCount(0);

    // Ничего не удалено
    await expect(rows).toHaveCount(count);
    await expect(rows.filter({ hasText: 'הטלפון הזה' })).toHaveCount(1);
  });
});
